import { defineSchema, lazySchema } from "../schemas/index.js";
import { agentConversationDiagnostic } from "../trigger/target.js";
export const getRunKindSchema = defineSchema((v) => v.enum(["agent", "workflow", "task", "eval"]));
export const getRunStatusSchema = defineSchema((v) => v.enum(["pending", "running", "waiting", "completed", "failed", "cancelled"]));
export const getRunOwnerSchema = defineSchema((v) => v.object({
    kind: v.enum(["conversation", "project"]),
    id: v.string(),
}));
export const getRunRuntimeTargetKindSchema = defineSchema((v) => v.enum(["main_branch", "environment", "preview_branch"]));
export const getRunTriggerKindSchema = defineSchema((v) => v.enum(["manual", "schedule", "webhook", "api"]));
export const getRunExecutionErrorSchema = defineSchema((v) => v.object({
    message: v.string(),
    code: v.string().optional(),
    detail: v.unknown().optional(),
}));
// Lowercase hex sha256 of the canonical JSON Schema a run was admitted against.
const getRunSchemaIdentitySchema = defineSchema((v) => v.string().regex(/^[0-9a-f]{64}$/).nullable().optional());
// A run a waiting run depends on (waiting_reason `child_run`), with the tool call or workflow node
// that started it. Several entries mean the run waits for all of them.
const getRunWaitingDependencySchema = defineSchema((v) => v.object({
    kind: v.literal("run"),
    run_id: v.string().min(1),
    correlation: v.object({
        kind: v.enum(["tool_call", "workflow_node"]),
        id: v.string().min(1),
    }),
}));
export const getRunSchema = defineSchema((v) => v.object({
    run_id: v.string(),
    kind: getRunKindSchema(),
    status: getRunStatusSchema(),
    owner: getRunOwnerSchema(),
    parent_run_id: v.string().nullable(),
    root_run_id: v.string(),
    waiting_reason: v.string().nullable(),
    // Active dependencies while `waiting_reason` is `child_run`; null otherwise, and absent from
    // APIs that predate it.
    waiting_on: v.array(getRunWaitingDependencySchema()).nullable().optional(),
    metadata: v.unknown().nullable(),
    target: v.string().nullable(),
    workflow_id: v.string().nullable(),
    schedule_id: v.string().nullable(),
    batch_id: v.string().nullable(),
    runtime_target_kind: getRunRuntimeTargetKindSchema().nullable(),
    runtime_target_environment_id: v.string().nullable(),
    runtime_target_branch_id: v.string().nullable(),
    // Run I/O contract: `input` and `output` are any JSON value (an agent's output is its final
    // text). The schema identities are the lowercase hex sha256 of the canonical JSON Schema the
    // run was admitted against, null when the target declares none, and absent from APIs that
    // predate them.
    input: v.unknown().nullable(),
    config: v.unknown().nullable(),
    output: v.unknown().nullable(),
    input_schema_sha256: getRunSchemaIdentitySchema(),
    output_schema_sha256: getRunSchemaIdentitySchema(),
    error: getRunExecutionErrorSchema().nullable(),
    logs: v.string().nullable(),
    artifacts: v.array(v.unknown()),
    duration_ms: v.number().int().nonnegative().nullable(),
    exit_code: v.number().int().nullable(),
    start_mode: v.string().nullable(),
    timeout_seconds: v.number().int().positive().nullable(),
    backoff_limit: v.number().int().nonnegative().nullable(),
    trigger_kind: getRunTriggerKindSchema().nullable(),
    trigger_id: v.string().nullable(),
    created_by: v.string().nullable(),
    updated_at: v.string(),
    created_at: v.string(),
    started_at: v.string().nullable(),
    completed_at: v.string().nullable(),
}));
export const getCreateRunResponseSchema = defineSchema((v) => v.object({
    accepted: v.boolean(),
    duplicate: v.boolean().optional(),
    run: v.union([
        getRunSchema(),
        v.object({ run_id: v.string().min(1), status: getRunStatusSchema() }),
    ]),
}));
export const getScheduleRunCreateResponseSchema = defineSchema((v) => v.object({
    run_id: v.string(),
    run_execution_id: v.string(),
    schedule_id: v.string(),
}));
const getScheduleReferenceSchema = defineSchema((v) => v.object({
    id: v.string(),
    name: v.string(),
    status: v.enum(["active", "paused", "deleting"]),
    target: v.object({
        kind: v.enum(["task", "workflow", "agent"]),
        id: v.string(),
        conversation_mode: v.enum(["create_new", "existing", "none"]).optional(),
        conversation_id: v.string().nullable().optional(),
    }).superRefine(({ kind, conversation_mode, conversation_id }, context) => {
        if (kind !== "agent" &&
            (conversation_mode !== undefined || conversation_id !== undefined)) {
            context.addIssue({
                code: "custom",
                message: "Schedule target conversation fields are valid only for agent targets.",
            });
        }
        if (kind === "agent") {
            const detail = agentConversationDiagnostic("Schedule target", conversation_mode, conversation_id);
            if (detail !== null) {
                context.addIssue({ code: "custom", message: detail });
            }
        }
    }).transform(({ kind, id, conversation_mode, conversation_id }) => {
        if (kind !== "agent")
            return { kind, id };
        return {
            kind,
            id,
            ...(conversation_mode === undefined ? {} : { conversationMode: conversation_mode }),
            ...(conversation_id === undefined ? {} : { conversationId: conversation_id }),
        };
    }),
    definition_source: v.enum(["manual", "source"]),
    source_trigger_id: v.string().nullable(),
    timeout_seconds: v.number().int().positive(),
}));
/** Schedule list response, read from the canonical `data` list key. */
export const getScheduleReferenceListSchema = defineSchema((v) => v.object({ data: v.array(getScheduleReferenceSchema()) }));
export const getCancelRunResponseSchema = defineSchema((v) => v.object({
    cancelled: v.boolean(),
    run: getRunSchema(),
}));
export const getRunEventSchema = defineSchema((v) => v.object({
    event_id: v.number().int().nonnegative(),
    event_type: v.string(),
    payload: v.unknown(),
    created_at: v.string(),
}));
export const getPageInfoSchema = defineSchema((v) => v.object({
    self: v.string().nullable(),
    first: v.literal(null),
    next: v.string().nullable(),
    prev: v.string().nullable(),
}));
export const getRunEventListSchema = defineSchema((v) => v.object({
    data: v.array(getRunEventSchema()),
    page_info: getPageInfoSchema(),
}));
export const getRunListSchema = defineSchema((v) => v.object({
    data: v.array(getRunSchema()),
    page_info: getPageInfoSchema(),
}));
/**
 * Zod schema for a canonical durable run whose `duration_ms` and
 * `backoff_limit` are non-negative integers and whose `timeout_seconds` is a
 * positive integer when present.
 */
export const RunSchema = lazySchema(getRunSchema);
/** Zod schema for a create-run response. */
export const CreateRunResponseSchema = lazySchema(getCreateRunResponseSchema);
/** Zod schema for a schedule-triggered create-run response. */
export const ScheduleRunCreateResponseSchema = lazySchema(getScheduleRunCreateResponseSchema);
/**
 * Zod schema for the schedule references needed to trigger source schedules.
 * Each source-schedule `timeout_seconds` value is a positive integer.
 */
export const ScheduleReferenceListSchema = lazySchema(getScheduleReferenceListSchema);
/** Zod schema for a cancel-run response. */
export const CancelRunResponseSchema = lazySchema(getCancelRunResponseSchema);
/** Zod schema for a run event whose `event_id` is a non-negative integer. */
export const RunEventSchema = lazySchema(getRunEventSchema);
/** Zod schema for a paginated run-event response. */
export const RunEventListSchema = lazySchema(getRunEventListSchema);
/** Zod schema for a paginated project-run response. */
export const RunListSchema = lazySchema(getRunListSchema);
